import @vibe/compiler { configure_cfg_flags }
import @vibe/compiler/checker { set_error_row_checked }
import @vibe/compiler/core { namespace_rename_originals_snapshot }
import @vibe/compiler/cache {
  ast_binary_write_module, ast_binary_write_string, ast_binary_write_svarint,
  ast_binary_write_varint, ast_binary_write_bool
}
import @vibe/compiler/codegen/wasi {
  PreludeModuleBatch, prelude_with_module_batch_executor
}
import @vibe/compiler/entry/compiler/file_compile {
  compile_file_fs_mode_rc_body_cached_split
}

let totals: Array[Int] = [0, 0, 0, 0, 0, 0, 0]
let common: Array[Int] = [0, 0, 0, 0]
let count: Array[Int] = [0]
let largest: Array[Int] = [0, 0]
fn clear_bytes(bytes: Bytes) -> Int = wasm
"local.get $bytes i32.wrap_i64 i32.const 0 i32.store offset=4 i64.const 0"
fn strings(buffer: Bytes, values: Array[String]) -> Unit {
  ast_binary_write_varint(buffer, Array::length(values))
  for value in values { ast_binary_write_string(buffer, value) }
  ()
}
fn pairs(buffer: Bytes, values: Array[(String, String)]) -> Unit {
  ast_binary_write_varint(buffer, Array::length(values))
  for pair in values {
    ast_binary_write_string(buffer, pair.0)
    ast_binary_write_string(buffer, pair.1)
  }
  ()
}
fn add(index: Int, amount: Int) -> Unit {
  Array::set(totals, index, Array::get(totals, index) + amount)
}
fn measure(batch: PreludeModuleBatch) -> Unit with Exception {
  let buffer = Bytes::with_capacity(64 * 1024 * 1024)
  let modules = Array::length(batch.parts)
  Array::set(count, 0, modules)
  ast_binary_write_varint(buffer, Array::length(batch.offsets))
  let mut i = 0
  while i < Array::length(batch.offsets) {
    ast_binary_write_svarint(buffer, Array::get(batch.offsets, i))
    ast_binary_write_string(buffer, Array::get(batch.keys, i))
    i = i + 1
  }
  Array::set(common, 0, Bytes::length(buffer))
  clear_bytes(buffer)
  strings(buffer, batch.env.trait_facts.wrapper_names)
  strings(buffer, batch.env.trait_facts.explicit_ops)
  Array::set(common, 1, Bytes::length(buffer))
  clear_bytes(buffer)
  pairs(buffer, namespace_rename_originals_snapshot())
  Array::set(common, 2, Bytes::length(buffer))
  clear_bytes(buffer)
  pairs(buffer, batch.env.alias_renames)
  ast_binary_write_bool(buffer, batch.env.calls_host_future)
  ast_binary_write_bool(buffer, batch.env.waiter_hooks)
  ast_binary_write_string(buffer, batch.env.aw_note)
  Array::set(common, 3, Bytes::length(buffer))
  i = 0
  while i < modules {
    clear_bytes(buffer)
    ast_binary_write_module(buffer, Array::get(batch.parts, i))
    let own = Bytes::length(buffer)
    add(0, own)
    if own > Array::get(largest, 0) { Array::set(largest, 0, own) } else ()
    clear_bytes(buffer)
    ast_binary_write_module(buffer, Array::get(batch.contexts, i))
    let interfaces = Bytes::length(buffer)
    add(1, interfaces)
    if interfaces > Array::get(largest, 1) { Array::set(largest, 1, interfaces) } else ()
    let mut j = 0
    while j < 4 { add(j + 2, Array::get(common, j)); j = j + 1 }
    clear_bytes(buffer)
    ast_binary_write_string(buffer, "vibe-module-trait-job-1")
    ast_binary_write_string(buffer, "f\{i}")
    let inner = Bytes::length(buffer) + own + interfaces + Array::get(common, 0) + Array::get(common, 1) + Array::get(common, 2)
    ast_binary_write_string(buffer, "vibe-prelude-module-job-1")
    ast_binary_write_varint(buffer, inner)
    ast_binary_write_string(buffer, if i == batch.entry_fid { batch.entry_name } else { "" })
    add(6, Bytes::length(buffer))
    i = i + 1
  }
  throw("shared-context measurement complete")
}
fn main() -> Unit allows Env + Exception + Fs {
  configure_cfg_flags()
  set_error_row_checked(true)
  handle {
    let unused = prelude_with_module_batch_executor(measure, () -> Bytes with Env + Exception + Fs {
      compile_file_fs_mode_rc_body_cached_split(Env::get("VIBE_LOWERING_INPUT"), Env::get("VIBE_LOWERING_ENTRY"), "off", true)
    })
    throw("measurement did not reach the batch")
  } with { Exception::Throw(message) => {
    if message != "shared-context measurement complete" { throw(message) } else ()
  } }
  let names = ["own", "interfaces", "typed", "facts", "namespace", "environment", "headers"]
  let mut text = "modules\t\{Array::get(count, 0)}\n"
  let mut i = 0
  while i < 7 {
    text = text + "\{Array::get(names, i)}\t\{Array::get(totals, i)}\n"
    i = i + 1
  }
  i = 0
  while i < 4 {
    text = text + "shared_\{Array::get(names, i + 2)}\t\{Array::get(common, i)}\n"
    i = i + 1
  }
  text = text + "largest_own\t\{Array::get(largest, 0)}\nlargest_interfaces\t\{Array::get(largest, 1)}\n"
  Fs::write_file(Env::get("VIBE_LOWERING_OUTPUT"), text)
}

