import os, subprocess, time, json, hashlib, shutil, statistics
from pathlib import Path
w=Path.cwd(); lab=w/'_build/shared-context-20261013'; corpus=lab/'corpus'
variants={key:dict(native=lab/key/'viberun',images=lab/key/'images',compiler=lab/key/'compiler.wasm') for key in ['a','b']}
native=variants['a']['native'];images=variants['a']['images'];compiler=variants['a']['compiler']
assert corpus.exists()
files=sorted((corpus/'lib').rglob('*'))
h=hashlib.sha256()
for p in files:
 if p.is_file():h.update(str(p.relative_to(corpus)).encode()+b'\0'+p.read_bytes())
receipts={'corpus_sha256':h.hexdigest(),'compiler_sha256':hashlib.sha256(compiler.read_bytes()).hexdigest(),'runner_sha256':hashlib.sha256(native.read_bytes()).hexdigest(),'images':json.loads((images/'build.json').read_text())}
receipts['candidate']={k:hashlib.sha256(v.read_bytes()).hexdigest() if k!='images' else json.loads((v/'build.json').read_text()) for k,v in variants['b'].items()}
env={k:v for k,v in os.environ.items() if not k.startswith('VIBE_')}
env.update(VIBE_LIB=str(corpus/'lib'),VIBE_PREOPEN_DIR=str(corpus),VIBE_RC='1',VIBE_UNSTABLE='1',VIBE_IMPORT_ABI='raw',VIBE_CHECKED_MODULE_CACHE='off',VIBE_CODEGEN_BODY_CACHE='off',VIBE_DISABLE_PERSISTENT_ARTIFACT_CACHE='1',VIBE_NATIVE_CACHE_DIR=str(lab/'native-cache-final'))
previous=json.loads((lab/'comparison-final.json').read_text())
assert previous['receipts']==receipts
rows=previous['samples']
def rss_family(pid):
 infos={}
 for p in Path('/proc').iterdir():
  if not p.name.isdigit():continue
  try:
   stat=(p/'stat').read_text().rsplit(')',1)[1].split(); infos[int(p.name)]=(int(stat[1]),int(stat[21])*os.sysconf('SC_PAGE_SIZE'))
  except (FileNotFoundError,ProcessLookupError,PermissionError,IndexError):pass
 found={pid}; changed=True
 while changed:
  before=len(found); found.update(p for p,(parent,rss) in infos.items() if parent in found);changed=len(found)!=before
 return sum(infos.get(p,(0,0))[1] for p in found)
def run(subject,config,round,temperature,cache):
 variant=variants['b' if config in ['b','e'] else 'a'];native=variant['native'];images=variant['images'];compiler=variant['compiler']
 target=lab/'runs-final'/f'{subject}-{config}-{round}-{temperature}.wasm'; target.parent.mkdir(exist_ok=True)
 current=env|dict(VIBE_BUILD_CACHE_DIR=str(cache))
 input=subjects[subject][0]; entry=subjects[subject][1]
 if config=='w':
  current['VIBE_FS_COMPILE']='1';cmd=[str(native),str(compiler),input,str(target),entry]
 elif config in ['d','e']:
  current.update(VIBE_LOWERING_MODE='serial',VIBE_LOWERING_INPUT=input,VIBE_LOWERING_ENTRY=entry,VIBE_LOWERING_OUTPUT=str(target))
  cmd=[str(native),str(images/'compile.wasm')]
 else:
  current['VIBE_LOWERING_TRACE_OUT']=str(target)+'.trace.json'
  cmd=['node',str(lab/('b' if config=='b' else 'a')/'frontend.mjs'),str(compiler),input,str(target),entry,'2',str(corpus),str(images),str(native)]
 out=Path(str(target)+'.out').open('w');err=Path(str(target)+'.err').open('w')
 started=time.monotonic();p=subprocess.Popen(cmd,cwd=corpus,env=current,stdout=out,stderr=err);peak=0
 while p.poll() is None:
  peak=max(peak,rss_family(p.pid));time.sleep(.025)
  assert time.monotonic()-started<600
 wall=time.monotonic()-started;out.close();err.close();code=p.wait()
 row=dict(subject=subject,config=config,round=round,temperature=temperature,wall_s=wall,peak_process_tree_rss_sum_bytes=peak,exit=code)
 if code==0:
  row['wasm_sha256']=hashlib.sha256(target.read_bytes()).hexdigest()
  if config in ['a','b']:row['phases']=json.loads(Path(str(target)+'.trace.json').read_text())
 else:row['error']=Path(str(target)+'.err').read_text()[-8000:]
 rows.append(row);(lab/'comparison-final.json').write_text(json.dumps({'receipts':receipts,'scope':'Merged retained-parent baseline a vs immutable shared-context b; N3 alternating TaskGroup2 cold/warm pairs on one frozen merged-main corpus. Each pair has isolated guest parsed-source cache; checked-module, codegen-body and artifact caches off. Native JIT primed. Process-tree RSS sampled every25ms (shared mappings may be counted twice). No concurrent builds/tests/edits. Additional N3 fresh candidate serial-split and baseline ordinary-whole controls. Output Wasm hashes agree across old/new TaskGroup and serial split. Ordinary whole outputs are separately consistent and differ from split outputs. Worker phase includes parent encoding/decoding/merge; context serialization occurs once in b.','samples':rows},indent=2)+'\n')
 print(subject,config,round,temperature,code,f'{wall:.3f}s',f'{peak/2**20:.1f}MiB',flush=True)
 assert code==0,row
 return row
subjects={'compiler':('lib/@vibe/compiler/tests/codegen_lexer_test.vibe','__no_entry__'),'cli':('lib/@vibe/cli/entry.vibe','cli_main')}
# Prime native compilation for all emitted images independently of guest caches.
for variant in variants.values():
 for name in [variant['compiler'],variant['images']/'compile.wasm',variant['images']/'coordinator.component.wasm',variant['images']/'worker.wasm']:
  subprocess.run([str(variant['native']),str(name)],cwd=corpus,env=env,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=120)
for subject in subjects:
 for round in range(3):
  for config in (['e','w'] if round%2==0 else ['w','e']):
   existing=[r for r in rows if r['subject']==subject and r['round']==round and r['config']==config]
   if len(existing)==2: continue
   assert not existing
   cache=lab/'caches-final'/subject/str(round)/config;cache.mkdir(parents=True,exist_ok=False)
   cold=run(subject,config,round,'cold',cache);warm=run(subject,config,round,'warm',cache)
   assert cold['wasm_sha256']==warm['wasm_sha256']
  split={r['wasm_sha256'] for r in rows if r['subject']==subject and r['config']!='w'}
  whole={r['wasm_sha256'] for r in rows if r['subject']==subject and r['config']=='w'}
  assert len(split)==1 and len(whole)==1,(subject,split,whole)
print('All split outputs match; ordinary whole controls are independently consistent.',flush=True)
